<?php
if(!defined('SCHOOLOS_EXPERIENCE')){http_response_code(404);exit;}
function web_guide_data():array{return json_decode(file_get_contents(__DIR__.'/public_guides.json'),true,512,JSON_THROW_ON_ERROR);}
function web_guides():void{echo '<section class="section"><div class="notice">Release 5.3.0 · Guides describe permission-based workflows. Your available modules depend on school configuration. Download a PDF for offline reading or open the accessible web version. The owner guide covers all operational areas; specialist guides explain each account’s responsibilities.</div><div class="cards guides">';foreach(web_guide_data() as $key=>[$name,$sections])echo '<article><h3>'.e($name).'</h3><p>'.count($sections).' practical sections · setup, daily work and verification.</p><a href="?guide='.$key.'">Read guide →</a><a href="?guide='.$key.'&download=pdf">Download PDF ↓</a></article>';echo '</div></section>';}
function web_guide(string $key):void{$all=web_guide_data();if(!isset($all[$key])){http_response_code(404);web_head('documentation');echo '<section class="section"><h1>Guide not found</h1><a href="?page=documentation">Browse available guides</a></section>';web_foot();return;}[$name,$sections]=$all[$key];if(($_GET['download']??'')==='pdf'){$lines=['SCHOOLOS NIGERIA | Release 5.3.0',$name.' guide','Updated 23 October 2026 | Public operational guidance',''];foreach($sections as [$title,$body]){$lines[]=strtoupper($title);foreach(explode("\n",wordwrap($body,88,"\n",true)) as $line)$lines[]=$line;$lines[]='';} $lines[]='For current guidance, open SchoolOS > Help & role guides.';acPdf('SchoolOS-'.$key.'-Guide-5.3.0.pdf',$lines);}web_head('documentation');web_title('YOUR SCHOOLOS FIELD GUIDE',$name,'Release 5.3.0 · Read with your school’s policies and the permissions assigned to your account.');echo '<section class="section narrow"><a class="button" href="?guide='.e($key).'&download=pdf">Download this guide as PDF ↓</a><nav aria-label="Guide contents"><ol>';foreach($sections as $i=>[$title,$body])echo '<li><a href="#guide-'.(int)$i.'">'.e($title).'</a></li>';echo '</ol></nav>';foreach($sections as $i=>[$title,$body])echo '<article class="guide-section" id="guide-'.(int)$i.'"><h2>'.e($title).'</h2><p>'.e($body).'</p></article>';echo '<p><a href="?page=documentation">← All role guides</a></p></section>';web_foot();}
